        verify_cert = False if is_internal else True
        response = requests.get(url, params=parameters, headers=HEADERS, timeout=10, verify=verify_cert)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"Failed to access URL: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid data: response is not valid JSON. {e}")
    if not data:
        raise Exception("Empty data: no data received from API.")
    if isinstance(data, dict):
        data = [data]
    elif not isinstance(data, list):
        raise Exception("Invalid data: expected a list or dict.")
    df = pd.DataFrame(data)
    if df.empty:
        raise Exception("Empty data: DataFrame is empty.")
    numerical_cols = df.select_dtypes(include=['number']).columns.tolist()
    if not numerical_cols:
        raise Exception("Invalid data: no numerical columns to compute correlation.")
    corr = df[numerical_cols].corr()
    _, ax = sns.heatmap(corr, annot=True, cmap='coolwarm', square=True).figure.axes[0]
    return df, ax
